    args: [{ selector: "app-datatable", standalone: true, imports: [CommonModule, FormsModule], template: `<div class="datatable-wrapper position-relative">\r
    <!-- Loader overlay dentro do componente -->\r
    <div *ngIf="loading" class="loader-overlay-inner">\r
        <div class="spinner-border text-primary spinner-border-sm" role="status">\r
            <span class="visually-hidden">Carregando...</span>\r
        </div>\r
    </div>\r
\r
    <!-- Top Controls: Per Page and Search -->\r
    <div class="row mb-3 align-items-center">\r
        <div class="col-sm-12 col-md-6">\r
            <div class="d-flex align-items-center">\r
                <span class="small text-muted">Mostrar</span>\r
                <select class="form-select form-select-sm mx-2 w-auto" [(ngModel)]="pagination.per_page" (change)="onPerPageSelect()">\r
                    <option *ngFor="let opt of perPageOptions" [value]="opt">{{ opt }}</option>\r
                </select>\r
                <span class="small text-muted">registros</span>\r
            </div>\r
        </div>\r
        <div class="col-sm-12 col-md-6">\r
            <div class="d-flex justify-content-md-end align-items-center mt-2 mt-md-0">\r
                <label class="me-2 mb-0 small text-muted">Pesquisar:</label>\r
                <div class="input-group input-group-sm w-auto" style="max-width: 250px;">\r
                    <input type="search" \r
                           class="form-control" \r
                           [(ngModel)]="searchQuery" \r
                           (keydown.enter)="triggerSearch()" \r
                           (search)="onSearchClear($event)"\r
                           placeholder="Buscar...">\r
                    <button class="btn btn-primary" type="button" (click)="triggerSearch()">\r
                        <i class="fas fa-search"></i>\r
                    </button>\r
                </div>\r
            </div>\r
        </div>\r
    </div>\r
\r
    <!-- Table Content Wrapper -->\r
    <div class="table-responsive">\r
        <ng-content></ng-content>\r
    </div>\r
\r
    <!-- Bottom Controls: Pagination Info and Navigation -->\r
    <div class="row mt-3 align-items-center">\r
        <div class="col-sm-12 col-md-5">\r
            <div class="text-muted small">\r
                Mostrando de {{ pagination.from || 0 }} at\xE9 {{ pagination.to || 0 }} de {{ pagination.total }} registros\r
            </div>\r
        </div>\r
        <div class="col-sm-12 col-md-7">\r
            <nav aria-label="Navega\xE7\xE3o de p\xE1gina" *ngIf="pagination.last_page >= 1">\r
                <ul class="pagination pagination-sm justify-content-md-end mb-0">\r
                    <!-- Anterior -->\r
                    <li class="page-item" [class.disabled]="pagination.current_page === 1">\r
                        <a class="page-link" href="javascript:void(0)" (click)="onPageClick(pagination.current_page - 1)">\r
                            <i class="fas fa-chevron-left small"></i>\r
                        </a>\r
                    </li>\r
                    \r
                    <!-- N\xFAmeros -->\r
                    <li class="page-item" *ngFor="let p of getVisiblePages()" [class.active]="pagination.current_page === p" [class.disabled]="p === '...'">\r
                        <a class="page-link" href="javascript:void(0)" (click)="onPageClick(p)">\r
                            {{ p }}\r
                        </a>\r
                    </li>\r
                    \r
                    <!-- Pr\xF3ximo -->\r
                    <li class="page-item" [class.disabled]="pagination.current_page === pagination.last_page">\r
                        <a class="page-link" href="javascript:void(0)" (click)="onPageClick(pagination.current_page + 1)">\r
                            <i class="fas fa-chevron-right small"></i>\r
                        </a>\r
                    </li>\r
                </ul>\r
            </nav>\r
        </div>\r
    </div>\r
</div>\r
`, styles: ["/* src/app/shared/components/datatable/datatable.component.scss */\n.datatable-wrapper {\n  min-height: 100px;\n}\n.loader-overlay-inner {\n  position: absolute;\n  top: 50px;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  background: rgba(255, 255, 255, 0.5);\n  z-index: 10;\n  display: flex;\n  justify-content: center;\n  align-items: flex-start;\n  padding-top: 50px;\n}\n.pagination .page-link {\n  color: #4e73df;\n  box-shadow: none;\n}\n.pagination .page-link:focus {\n  box-shadow: 0 0 0 0.2rem rgba(78, 115, 223, 0.25);\n}\n.pagination .page-item.active .page-link {\n  background-color: #4e73df;\n  border-color: #4e73df;\n  color: white;\n}\n.pagination .page-item.disabled .page-link {\n  color: #858796;\n  background-color: #fff;\n  border-color: #dddfeb;\n}\n::ng-content table {\n  margin-bottom: 0;\n}\n/*# sourceMappingURL=datatable.component.css.map */\n"] }]
