        provider_id: this.prov.id,
        event_id: this.event.id,
        message: this.messageLink || "!",
        emails: this.emailsLink,
        copyMe: this.copyMeLink,
        attachment: this.attachmentLink,
        link: token,
        linkEmail: this.linkEmail,
        type: this.prov.table
